import { readFileSync } from "node:fs"
import { zstdDecompressSync } from "node:zlib"
function decode(f){const b=readFileSync(f);const starts=[];for(let i=0;i+4<=b.length;i++){if(b[i]===0x28&&b[i+1]===0xb5&&b[i+2]===0x2f&&b[i+3]===0xfd)starts.push(i)}let t="";for(let k=0;k<starts.length;k++){const end=k+1<starts.length?starts[k+1]:b.length;t+=zstdDecompressSync(b.subarray(starts[k],end)).toString("utf8")}return t.split("\n").filter(Boolean).map(l=>{try{return JSON.parse(l)}catch{return null}}).filter(Boolean)}
const len=v=>{if(!v)return 0;if(typeof v==="string")return v.length;if(Array.isArray(v))return v.reduce((a,x)=>a+len(x),0);if(typeof v==="object")return Object.values(v).reduce((a,x)=>a+len(x),0);return 0}
const base="E:/DSH/.dsh/sessions/"
const files={
 A1:"--E-DSH-focus-guard-main--/session-73a4980a-3dea-4d2d-916a-db5ce1ba99e6/session.v4.jsonl.zstd",
 A2:"--E-DSH-focus-guard-main--/session-d52c937b-46c0-43ba-896c-74702b7a83ce/session.v4.jsonl.zstd",
 B:"--E-DSH-focus-guard-main--/session-553a2558-5d53-4fb0-b7dc-c00da9e7ce08/session.v4.jsonl.zstd",
 T:"--E-DSH-focus-guard-main--/b7a1a8d5-be2e-4012-9e80-1cca4f6dfa6b/session.v4.jsonl.zstd"
}
for(const [tag,rel] of Object.entries(files)){
 const lines=decode(base+rel)
 const h=lines.find(l=>l.type==="request/header")
 const tools=(h&&h.data&&h.data.header&&h.data.header.tools)||[]
 const sysMsgs=lines.filter(l=>l.type==="system/message")
 const sysText=sysMsgs.map(l=>{const c=l.data&&l.data.message&&l.data.message.content;return typeof c==="string"?c:Array.isArray(c)?c.map(x=>x.text||"").join("\n"):""}).join("\n")
 const tc=lines.filter(l=>l.type==="tool/call").map(l=>(l.data&&l.data.call&&l.data.call.name)||(l.data&&l.data.name)||"?")
 const tr=lines.filter(l=>l.type==="tool/result")
 const steps=lines.filter(l=>l.type==="step/start").length
 console.log("=== "+tag)
 console.log("steps",steps,"tools",tools.length,"schema",JSON.stringify(tools).length)
 console.log("sysMsgs",sysMsgs.length,"sysChars",sysText.length,"hasDegraded",sysText.includes("focus-guard-degraded"),"mentionsFG",sysText.includes("FocusGuard")||sysText.includes("focus-guard"))
 console.log("toolNames",tools.map(t=>t.name).filter(n=>n.includes("fg")||n.includes("accur")||n.includes("mcp")).slice(0,12).join(","))
 console.log("toolCallTotal",tc.length,"distinct",Object.entries(tc.reduce((m,n)=>(m[n]=(m[n]||0)+1,m),{})).map(([k,v])=>k+":"+v).join(" "))
 console.log("toolResultChars",tr.reduce((a,l)=>a+len(l.data&&l.data.message&&l.data.message.content),0))
 console.log("userChars",lines.filter(l=>l.type==="user/message").reduce((a,l)=>a+len(l.data&&l.data.message&&l.data.message.content),0))
}
'@
Set-Content -Path "$env:TEMP\fg-detail.mjs" -Value $code -Encoding UTF8
